use gitfleet_core::{application::*,inspection::Cancellation,writes::Options};
use std::{fs,path::Path,process::Command};
fn git(root:&Path,args:&[&str])->String {let o=Command::new("git").current_dir(root).env("GIT_CONFIG_GLOBAL","/dev/null").env("GIT_CONFIG_NOSYSTEM","1").args(["-c","core.hooksPath=","-c","maintenance.auto=false","-c","gc.auto=0"]).args(args).output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));String::from_utf8(o.stdout).unwrap().trim().into()}
fn main() {
 let root=std::path::PathBuf::from(std::env::args().nth(1).unwrap());assert!(root.join(".gitfleet-m3-fixture").is_file());let repo=root.join("workspace/repository");fs::create_dir_all(&repo).unwrap();git(&repo,&["-c","init.templateDir=","init","-q","-b","main"]);
 for (key,value) in [("user.name","Native HTTPS fixture"),("user.email","fixture@example.invalid"),("commit.gpgsign","false"),("core.hooksPath","")] {git(&repo,&["config",key,value]);}
 fs::write(repo.join("fixture.txt"),b"Native HTTPS baseline\n").unwrap();git(&repo,&["add","fixture.txt"]);git(&repo,&["commit","-qm","Native HTTPS baseline"]);let baseline=git(&repo,&["rev-parse","HEAD"]);git(&repo,&["remote","add","origin","https://github.com/octocat/Hello-World.git"]);fs::write(repo.join("fixture.txt"),b"Staged fixture content\n").unwrap();git(&repo,&["add","fixture.txt"]);fs::write(repo.join("fixture.txt"),b"Working content outside index\n").unwrap();fs::write(repo.join("untracked.txt"),b"Preserve native fixture\n").unwrap();
 let state=root.join("state");let mut app=Application::open(&state,Options::default()).unwrap();let picker=app.register_directory(&root.join("workspace")).unwrap();app.request(app.epoch(),Request::Create {name:"Public HTTPS native acceptance".into(),picker}).unwrap();let Data::Workspaces(list)=app.request(app.epoch(),Request::Workspaces {}).unwrap().data else {panic!()};let workspace=list.active.unwrap();let Data::Inventory(inv)=app.request(app.epoch(),Request::Inventory {workspace:workspace.clone()}).unwrap().data else {panic!()};let worktree=inv.entries[0].id.0.clone();let Data::Review(r)=app.request(app.epoch(),Request::ReviewTrust {workspace:workspace.clone(),worktrees:vec![worktree.clone()]}).unwrap().data else {panic!()};let (cap,_)=app.begin_confirmation(&r.id).unwrap();app.confirm(cap,true,Cancellation::default()).unwrap();app.shutdown().unwrap();drop(app);
 println!("{}",serde_json::to_string_pretty(&serde_json::json!({"root":root,"repository":repo,"state":state,"isolated_home":root.join("home"),"workspace":workspace,"worktree":worktree,"baseline_oid":baseline,"remote":"https://github.com/octocat/Hello-World.git","provenance":"Local disposable checkout with fixture trust only. Zero observation/capture/import records seeded. All network actions require actual native approval."})).unwrap());
}
